                for (i, (start, end)) in ranges.iter().enumerate() {
                    if i > 0 {
                        write!(f, " | ")?;
                    }
                    write!(f, "{:?}..{:?}", start, end)?;
                }
                Ok(())
            }"""
new = """            ParsingToken::NegCharClass { ranges } => {
                write!(f, "!(")?;
                for (i, (start, end)) in ranges.iter().enumerate() {
                    if i > 0 {
                        write!(f, " | ")?;
                    }
                    write!(f, "{:?}..{:?}", start, end)?;
                }
                write!(f, ")")
            }"""
assert old in src
src = src.replace(old, new, 1)
open(path, 'w', encoding='utf-8').write(src)
print("neg display updated")
